package es.foco.next.ui;
import static org.junit.Assert.*;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.view.*;import android.widget.*;
import es.foco.next.R;import es.foco.next.core.*;import es.foco.next.data.Repository;import es.foco.next.runtime.FocusAccessibilityService;
import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.util.ReflectionHelpers;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w411dp-h915dp-420dpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class CalmVisualTest {
 private void install(String p,String label){
  Context c=RuntimeEnvironment.getApplication();PackageInfo info=new PackageInfo();info.packageName=p;info.applicationInfo=new ApplicationInfo();info.applicationInfo.packageName=p;info.applicationInfo.nonLocalizedLabel=label;info.applicationInfo.icon=R.drawable.leaf;
  ActivityInfo activity=new ActivityInfo();activity.name=p+".Main";activity.packageName=p;activity.applicationInfo=info.applicationInfo;activity.exported=activity.enabled=true;info.activities=new ActivityInfo[]{activity};Shadows.shadowOf(c.getPackageManager()).installPackage(info);
  ResolveInfo r=new ResolveInfo();r.activityInfo=activity;r.nonLocalizedLabel=label;Shadows.shadowOf(c.getPackageManager()).addResolveInfoForIntent(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),r);
 }
 @Before public void prepare(){Context c=RuntimeEnvironment.getApplication();ReflectionHelpers.callStaticMethod(Repository.class,"resetForTests");c.deleteFile("focus-lite-v1.json");c.deleteFile("focus-state-v1.json");c.getSharedPreferences("foco-notebook",0).edit().clear().commit();c.getSharedPreferences("foco-daily-reminder",0).edit().clear().commit();ReflectionHelpers.callStaticMethod(es.foco.next.runtime.CalmAudio.class,"resetForTests");c.getSharedPreferences("foco-soundscape",0).edit().clear().commit();ReflectionHelpers.setStaticField(SceneTheme.class,"wallClock",java.time.Clock.fixed(java.time.LocalDateTime.of(2026,10,26,12,0).atZone(java.time.ZoneId.systemDefault()).toInstant(),java.time.ZoneOffset.UTC));Alternatives.invalidate();install("org.readera","ReadEra");install("com.duolingo","Duolingo");install("md.obsidian","Obsidian");install("com.facebook.katana","Facebook");install("com.google.android.apps.books","Google Play Libros");install("com.gtl.nextory","Nextory");install("com.syc.librototal.El_Libro_Total","El Libro Total");install("some.bible.app","Biblia");install("com.samsung.android.app.notes","Notes");install("com.google.android.keep","Notas de Keep");install("com.samsung.android.app.reminder","Reminder");install("com.samsung.android.calendar","Calendario");AppConfig a=Repository.get(c).config();a.returnApp="org.readera";a.watchedApps.add("feed.app");Repository.get(c).saveConfig(a);}
 private void export(View v,String name)throws Exception{
  int w=1080,h=2400;v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);
  Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(v.getContext().getColor(R.color.surface));v.draw(canvas);
  File folder=new File(System.getProperty("user.dir"),"../verification/release-058");folder.mkdirs();try(OutputStream out=new FileOutputStream(new File(folder,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}
  assertTrue(Color.green(b.getPixel(w/2,100))>0);
 }
 @Test public void exportsRealLightInterfaceAndInstalledAlternatives()throws Exception{var c=Robolectric.buildActivity(MainActivity.class).setup().visible();try{assertEquals(android.content.res.Configuration.UI_MODE_NIGHT_NO,c.get().getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK);assertEquals(4,((LinearLayout)c.get().findViewById(R.id.navigation)).getChildCount());export((View)c.get().findViewById(R.id.root).getParent(),"foco-calm-claro");assertFalse(ReflectionHelpers.<QuietMusic>getField(c.get(),"music").playing());}finally{c.pause().stop().destroy();}}
 @Test @Config(qualifiers="w411dp-h915dp-night-420dpi") public void exportsDarkInterface()throws Exception{ReflectionHelpers.setStaticField(SceneTheme.class,"wallClock",java.time.Clock.fixed(java.time.LocalDateTime.of(2026,10,26,22,0).atZone(java.time.ZoneId.systemDefault()).toInstant(),java.time.ZoneOffset.UTC));var c=Robolectric.buildActivity(MainActivity.class).setup().visible();try{assertEquals(android.content.res.Configuration.UI_MODE_NIGHT_YES,c.get().getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK);assertEquals(android.graphics.Color.rgb(8,23,15),c.get().getColor(R.color.surface));export((View)c.get().findViewById(R.id.root).getParent(),"foco-calm-oscuro");}finally{c.pause().stop().destroy();}}
 @Test public void exportsActualCalmBlockAndHasNoContinueControl()throws Exception{var c=Robolectric.buildService(FocusAccessibilityService.class).create();FocusOverlay o=new FocusOverlay(c.get());try{o.block(Repository.get(c.get()).config(),3300000);View view=ReflectionHelpers.getField(o,"view");assertNotNull(view);export(view,"foco-calm-pausa");}finally{o.dismiss();c.destroy();}}
 @Test public void musicStopsWhenActivityLeavesForeground(){org.robolectric.shadows.ShadowMediaPlayer.setMediaInfoProvider(source->new org.robolectric.shadows.ShadowMediaPlayer.MediaInfo(120000,0));Shadows.shadowOf(RuntimeEnvironment.getApplication().getSystemService(android.media.AudioManager.class)).setNextFocusRequestResponse(android.media.AudioManager.AUDIOFOCUS_REQUEST_GRANTED);var c=Robolectric.buildActivity(MainActivity.class).setup().visible();var sound=Robolectric.buildService(es.foco.next.runtime.CalmAudioService.class).create();try{sound.get().onStartCommand(new Intent(),0,1);QuietMusic music=ReflectionHelpers.getField(c.get(),"music");assertTrue(music.playing());c.pause();assertFalse(music.playing());assertFalse(es.foco.next.runtime.CalmAudio.wanted());}finally{sound.destroy();c.stop().destroy();}}
 @Test public void realInstalledGalleryNeverIncludesFacebookAndCorrectlyGroupsBible(){var a=Robolectric.buildActivity(MainActivity.class).setup().visible();try{var list=Alternatives.installed(a.get(),Repository.get(a.get()).config());assertFalse(list.stream().anyMatch(e->e.pkg.equals("com.facebook.katana")));assertTrue(list.stream().anyMatch(e->e.label.equals("Biblia")&&e.group==0));assertTrue(list.stream().anyMatch(e->e.label.equals("Nextory")&&e.group==0));AppPicker.one(a.get(),p->{});var dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();var adapter=dialog.getListView().getAdapter();for(int i=0;i<adapter.getCount();i++)assertNotEquals("Facebook",adapter.getItem(i));}finally{a.pause().stop().destroy();}}
 private EditText editor(android.view.View v){if(v instanceof EditText)return (EditText)v;if(v instanceof android.view.ViewGroup){var group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++){EditText found=editor(group.getChildAt(i));if(found!=null)return found;}}return null;}
 @Test public void noteCanBeSavedDuringFocusLockWithoutChangingBudget()throws Exception{var a=Robolectric.buildActivity(MainActivity.class).setup().visible();try{Repository r=Repository.get(a.get());long elapsed=android.os.SystemClock.elapsedRealtime();for(int i=0;i<=5;i++){var in=new FocusEngine.Input();in.pkg="feed.app";in.interactive=true;in.boot=Repository.boot(a.get());in.day=java.time.LocalDate.now().toString();in.elapsed=elapsed+i*60000;in.wall=System.currentTimeMillis()+i*60000;r.sample(in,true);}assertTrue(r.locked());long end=r.state().window.elapsed;DailySpace.edit(a.get(),java.time.LocalDate.now().toString());Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();var dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();EditText field=editor(dialog.getWindow().getDecorView());assertNotNull(field);field.setText("Leer unas páginas y apuntar una idea.");dialog.getButton(android.app.AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(a.get().notebook().today().contains("apuntar"));assertEquals(end,r.state().window.elapsed);assertEquals(FocusEngine.BUDGET,r.state().usedMillis);android.view.View day=ReflectionHelpers.getField(a.get(),"dayCard");export(day,"foco-mi-dia");}finally{a.pause().stop().destroy();}}
 @Test public void denialKeepsDailyReminderOff(){var a=Robolectric.buildActivity(MainActivity.class).setup().visible();try{a.get().pendingReminderMinute=1200;a.get().onRequestPermissionsResult(52,new String[]{android.Manifest.permission.POST_NOTIFICATIONS},new int[]{android.content.pm.PackageManager.PERMISSION_DENIED});assertFalse(es.foco.next.runtime.DailyReminder.enabled(a.get()));}finally{a.pause().stop().destroy();}}
 @Test @Config(qualifiers="w411dp-h915dp-night-420dpi") public void daylightUsesBrightThemeEvenWhenSystemIsDark(){var c=Robolectric.buildActivity(MainActivity.class).setup().visible();try{assertEquals(android.content.res.Configuration.UI_MODE_NIGHT_NO,c.get().getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK);assertEquals(android.graphics.Color.rgb(15,36,25),c.get().getColor(R.color.surface));}finally{c.pause().stop().destroy();}}
}
